# Rebuild for aarch64 the third-party libraries whose source ships inside the UE 5.4 tree, and link the
# system libraries the editor needs. Outputs go where the patched .Build.cs files look for them.
#
# usage: build_intree.sh [step ...]     (no step = all, in this order)
# steps: shaderconductor nvtt ogg opus kissfft spirvreflect hlslcc vhacd speedtree syms
#        astcenc etc2comp png vorbis tbb strophe freeimage sndfile xml2
#
# Needs: cmake, ninja, python3, and for the system steps libfreeimage-dev, libsndfile1, libxml2-dev.
source "$(dirname "$0")/common.sh"

step_shaderconductor() {
    # DXC + ShaderConductor (the arm64 CMake branch is fixed by the main patch). Takes ~10 min.
    local s=$TP/ShaderConductor bd=$W/shaderconductor out=$E/Binaries/ThirdParty/ShaderConductor/Linux/$T
    mkdir -p "$bd" "$out"
    ( cd "$bd" && cmake -G Ninja -DCMAKE_C_COMPILER="$CLANG" -DCMAKE_CXX_COMPILER="$CLANGXX" -DCMAKE_BUILD_TYPE=RelWithDebInfo \
        -DSC_ARCH_NAME=arm64 -DCMAKE_CXX_FLAGS=-stdlib=libc++ \
        -DCMAKE_EXE_LINKER_FLAGS="-stdlib=libc++ $LLD" -DCMAKE_SHARED_LINKER_FLAGS="-stdlib=libc++ $LLD" \
        -DPYTHON_EXECUTABLE="$(command -v python3)" -DPython3_EXECUTABLE="$(command -v python3)" \
        -DSPIRV_CROSS_ENABLE_TESTS=OFF -DSC_EXPLICIT_DLLSHUTDOWN=ON -DDXC_EXPLICIT_DLLSHUTDOWN=ON "$s/ShaderConductor" \
        && ninja -j "$J" ) > "$LOG/shaderconductor.log" 2>&1 || { echo "!! shaderconductor failed (see $LOG/shaderconductor.log)"; return 1; }
    cp "$bd/Lib/libdxcompiler.so" "$bd/Lib/libShaderConductor.so" "$bd/Bin/ShaderConductorCmd" "$out/" && echo "ok   shaderconductor -> ${out#$UE_ROOT/}"
}

step_nvtt() {
    # nvTextureTools 2.0.8 (the version nvTextureTools.Build.cs uses), shared, no SSE
    local s=$TP/nvTextureTools/nvTextureTools-2.0.8/src bd=$W/nvtt out=$E/Binaries/ThirdParty/nvTextureTools/Linux/$T
    rm -rf "$bd"; mkdir -p "$bd" "$out"
    ( cd "$bd" && cmake -G Ninja -DCMAKE_C_COMPILER="$CLANG" -DCMAKE_CXX_COMPILER="$CLANGXX" -DCMAKE_BUILD_TYPE=Release \
        -DCMAKE_POSITION_INDEPENDENT_CODE=ON -DCMAKE_C_FLAGS=-w -DCMAKE_CXX_FLAGS="-w -stdlib=libc++ -std=c++14" \
        -DCMAKE_SHARED_LINKER_FLAGS="-stdlib=libc++ $LLD" -DCMAKE_EXE_LINKER_FLAGS="-stdlib=libc++ $LLD" \
        -DNVTT_SHARED=1 -DCMAKE_POLICY_VERSION_MINIMUM=3.5 "$s" && ninja -j "$J" ) > "$LOG/nvtt.log" 2>&1 \
        || { echo "!! nvtt failed (see $LOG/nvtt.log)"; return 1; }
    cp "$bd"/src/nvtt/libnvtt.so "$bd"/src/nvimage/libnvimage.so "$bd"/src/nvmath/libnvmath.so "$bd"/src/nvcore/libnvcore.so "$out/" \
        && echo "ok   nvtt -> ${out#$UE_ROOT/}"
}

step_ogg() {
    local d=$TP/Ogg/libogg-1.2.2
    if [ ! -f "$d/include/ogg/config_types.h" ]; then      # normally generated by configure
        cat > "$d/include/ogg/config_types.h" <<'EOF'
#ifndef __CONFIG_TYPES_H__
#define __CONFIG_TYPES_H__
#include <stdint.h>
typedef int16_t ogg_int16_t;
typedef uint16_t ogg_uint16_t;
typedef int32_t ogg_int32_t;
typedef uint32_t ogg_uint32_t;
typedef int64_t ogg_int64_t;
#endif
EOF
    fi
    mklib ogg "$d/lib/Unix/$T/libogg_fPIC.a" "$CC" "-I$d/include" -- "$d"/src/bitwise.c "$d"/src/framing.c
}

step_opus() {
    # the bundled configure does not configure off x86; compile the float build directly
    local d=$TP/libOpus/opus-1.1 src
    src="$(ls "$d"/celt/*.c | grep -v opus_custom_demo) $(ls "$d"/silk/*.c) $(ls "$d"/silk/float/*.c) $(ls "$d"/src/*.c | grep -v -e opus_compare -e _demo)"
    mklib opus "$d/Unix/$T/libopus_fPIC.a" "$CC" "-DOPUS_BUILD -DUSE_ALLOCA -DHAVE_LRINT -DHAVE_LRINTF -I$d/include -I$d/celt -I$d/silk -I$d/silk/float -I$d/src" -- $src
}

step_kissfft() {
    local d=$TP/Kiss_FFT/kiss_fft129
    mklib kissfft "$d/Lib/Linux/Release/$T/libKissFFT_fPIC.a" "$CC" "-I$d -I$d/tools" -- \
        "$d"/kiss_fft.c "$d"/tools/kiss_fftr.c "$d"/tools/kiss_fftnd.c "$d"/tools/kiss_fftndr.c
}

step_spirvreflect() {
    local d=$TP/SPIRV-Reflect
    mklib spirvreflect "$d/lib/Linux/$T/libSPIRV-Reflect.a" "$CC" "-I$d/SPIRV-Reflect -I$d/SPIRV-Reflect/include" -- "$d"/SPIRV-Reflect/spirv_reflect.c
}

step_hlslcc() {
    local d=$TP/hlslcc/hlslcc
    mklib hlslcc "$d/lib/Linux/$T/libhlslcc.a" "$CXX" "-std=c++17 -I$d/src/hlslcc_lib" -- "$d"/src/hlslcc_lib/*.cpp
}

step_vhacd() {
    local d=$TP/VHACD
    mklib vhacd "$d/Lib/Linux/$T/libVHACD_fPIC.a" "$CXX" "-std=c++14 -I$d/inc -I$d/public" -- "$d"/src/*.cpp
}

step_speedtree() {
    local d=$TP/SpeedTree/SpeedTreeSDK-v7.0
    mklib speedtree "$d/Lib/Linux/$T/Release/libSpeedTreeCore_fPIC.a" "$CXX" "-std=c++14 -I$d/Include -I$d/Source/Core -DSPEEDTREE_KEY=INSERT_KEY_HERE" -- \
        $(find "$d/Source/Core" -name "*.cpp")
}

step_syms() {
    local d=$E/Source/Runtime/SymsLib bd=$W/syms a
    rm -rf "$bd"; mkdir -p "$bd"
    ( cd "$bd" && cmake -G Ninja -DCMAKE_C_COMPILER="$CLANG" -DCMAKE_CXX_COMPILER="$CLANGXX" -DCMAKE_BUILD_TYPE=Release \
        -DCMAKE_POSITION_INDEPENDENT_CODE=ON -DCMAKE_C_FLAGS=-w -DCMAKE_CXX_FLAGS="-w -stdlib=libc++" "$d" && ninja ) > "$LOG/syms.log" 2>&1 \
        || { echo "!! syms failed (see $LOG/syms.log)"; return 1; }
    a=$(find "$bd" -name "*.a" | head -1)
    mkdir -p "$d/lib/Unix/$T" && cp "$a" "$d/lib/Unix/$T/libsyms_fPIC.a" && echo "ok   syms"
}

# ---- same path for x86 and arm64 in the .Build.cs: rebuilt over the x86 file, original kept as *.x86
step_astcenc() {
    local d=$TP/astcenc/4.2.0 out=$TP/astcenc/4.2.0/lib/Linux/Release/libastcenc-sse4.1-static.a
    keep_x86 "$out"
    mklib astcenc "$out" "$CXX" "-std=c++14 -DASTCENC_NEON=1 -DASTCENC_SSE=0 -DASTCENC_AVX=0 -DASTCENC_POPCNT=0 -DASTCENC_F16C=0 -I$d/Source" -- \
        $(ls "$d"/Source/astcenc_*.cpp)
}

step_etc2comp() {
    local d=$TP/etc2comp out=$TP/etc2comp/lib/Linux/Release/libEtcLib.a
    keep_x86 "$out"
    mklib etc2comp "$out" "$CXX" "-std=c++14 -I$d/EtcLib/Etc -I$d/EtcLib/EtcCodec" -- "$d"/EtcLib/Etc/*.cpp "$d"/EtcLib/EtcCodec/*.cpp
}

# ---- Epic ships arm64 archives of these, but not position independent / built against libstdc++
step_png() {
    local d=$TP/libPNG/libPNG-1.5.27 out=$TP/libPNG/libPNG-1.5.27/lib/Unix/$T/libpng.a
    keep_x86 "$out"
    mklib png "$out" "$CC" "-DPNG_ARM_NEON_OPT=0 -I$d -I$TP/zlib/1.3/include" -- $(ls "$d"/png*.c | grep -v pngtest)
}

step_vorbis() {
    local d=$TP/Vorbis/libvorbis-1.3.2 o=$TP/Ogg/libogg-1.2.2 L=$TP/Vorbis/libvorbis-1.3.2/lib/Unix/$T inc
    inc="-I$d/include -I$d/lib -I$o/include"
    for f in libvorbis.a libvorbisenc.a libvorbisfile.a; do keep_x86 "$L/$f"; done
    mklib vorbis "$L/libvorbis.a" "$CC" "$inc" -- $(ls "$d"/lib/*.c | grep -v -e vorbisenc.c -e vorbisfile.c -e barkmel.c -e tone.c -e psytune.c) \
      && mklib vorbisenc "$L/libvorbisenc.a" "$CC" "$inc" -- "$d"/lib/vorbisenc.c \
      && mklib vorbisfile "$L/libvorbisfile.a" "$CC" "$inc" -- "$d"/lib/vorbisfile.c
}

step_tbb() {
    # Epic's arm64 libtbb.a references libstdc++ (std::string ctors); the engine links libc++
    local d=$TP/Intel/TBB/IntelTBB-2019u8 L=$TP/Intel/TBB/IntelTBB-2019u8/lib/Linux/$T inc
    keep_x86 "$L/libtbb.a"; keep_x86 "$L/libtbbmalloc.a"
    mkdir -p "$W/tbbver" && printf '#define __TBB_VERSION_STRINGS(N) "TBB: BUILD_DATE\\t\\taarch64 rebuild\\n"\n' > "$W/tbbver/version_string.ver"
    inc="-std=c++14 -pthread -DUSE_PTHREAD -D__TBB_DYNAMIC_LOAD_ENABLED=0 -D__TBB_SOURCE_DIRECTLY_INCLUDED=1 -I$W/tbbver -I$d/include -I$d/src -I$d/src/rml/include -iquote $d/src/tbb"
    mklib tbb "$L/libtbb.a" "$CXX" "$inc -D__TBB_BUILD=1" -- $(ls "$d"/src/tbb/*.cpp) "$d"/src/rml/client/rml_tbb.cpp \
      && mklib tbbmalloc "$L/libtbbmalloc.a" "$CXX" "$inc -D__TBBMALLOC_BUILD=1 -fno-rtti -fno-exceptions" -- $(ls "$d"/src/tbbmalloc/*.cpp | grep -v proxy.cpp)
}

step_strophe() {
    # glibc >= 2.34 no longer exports the default-version __res_query that Epic's arm64 libstrophe calls
    # (XMPP fails to link). Add a one-function forwarder to res_query to the archive. Original kept as *.orig.
    local a
    mkdir -p "$W/strophe"
    cat > "$W/strophe/res_compat.c" <<'EOF'
#include <resolv.h>
int __res_query(const char *dname, int cls, int type, unsigned char *answer, int anslen)
{
    return res_query(dname, cls, type, answer, anslen);
}
EOF
    $CLANG -fPIC -O2 -c "$W/strophe/res_compat.c" -o "$W/strophe/res_compat.o" || return 1
    for a in Release/libstrophe_fPIC.a Debug/libstrophe_fPIC.a; do
        a=$TP/libstrophe/libstrophe-0.9.3/Lib/Unix/$T/$a
        [ -f "$a" ] || continue
        [ -e "$a.orig" ] || cp -a "$a" "$a.orig"
        cp -a "$a.orig" "$a" && $AR rs "$a" "$W/strophe/res_compat.o"
    done
    echo "ok   strophe (__res_query forwarder added)"
}

# ---- system libraries in place of x86-only shared objects
step_freeimage() {
    local f=$E/Binaries/ThirdParty/FreeImage/Linux/libfreeimage-3.18.0.so
    keep_x86 "$f"; ln -sf /usr/lib/aarch64-linux-gnu/libfreeimage.so.3 "$f" && echo "ok   freeimage -> system libfreeimage.so.3"
}
step_sndfile() {
    local f=$E/Binaries/ThirdParty/libsndfile/Linux/libsndfile.so.1
    keep_x86 "$f"; ln -sf /usr/lib/aarch64-linux-gnu/libsndfile.so.1 "$f" && echo "ok   sndfile -> system libsndfile.so.1"
}
step_xml2() {
    # no libxml2 source in the tree; its only user is the FBX module (a placeholder on arm64)
    local d=$TP/libxml2/libxml2-2.9.10/lib/$T
    mkdir -p "$d" && ln -sf /usr/lib/aarch64-linux-gnu/libxml2.a "$d/libxml2.a" && echo "ok   xml2 -> system libxml2.a"
}

run_steps "shaderconductor nvtt ogg opus kissfft spirvreflect hlslcc vhacd speedtree syms astcenc etc2comp png vorbis tbb strophe freeimage sndfile xml2" "$@"
